def process_idempotent_task(db, tenant_id: str, idempotency_key: str, payload: dict):
    payload_hash = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()
    query = """
    INSERT INTO tasks (tenant_id, idempotency_key, payload_hash, status)
    VALUES (%s, %s, %s, 'PROCESSING')
    ON CONFLICT (tenant_id, idempotency_key) DO UPDATE
    SET updated_at = NOW()
    RETURNING id, payload_hash, status;
    """
    row = db.execute(query, (tenant_id, idempotency_key, payload_hash)).fetchone()
    if row['payload_hash'] != payload_hash:
        raise ValueError('Idempotency conflict: key reused with different payload')
    return {'task_id': row['id'], 'status': row['status']}
